std::vector<const BriefingRow*> briefingRows(std::string_view mission, char side) {
    std::vector<const BriefingRow*> out;
    for (const BriefingRow& r : kRows)
        if (r.side == side && mission.size() == std::char_traits<char>::length(r.mission) &&
            std::equal(mission.begin(), mission.end(), r.mission, [](char x, char y) {
                return std::toupper(static_cast<unsigned char>(x)) == std::toupper(static_cast<unsigned char>(y));
            }))
            out.push_back(&r);
    return out;
}

